CREATE TYPE public.app_role AS ENUM ('customer','worker');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_own_edit ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_own_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.handle_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'full_name',NEW.raw_user_meta_data->>'name','')); IF NEW.raw_user_meta_data->>'account_role' IN ('customer','worker') THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,(NEW.raw_user_meta_data->>'account_role')::public.app_role); END IF; RETURN NEW; END $$;
CREATE TRIGGER skillconnect_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_signup();
CREATE FUNCTION public.choose_account_role(chosen public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Log in first'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),chosen) ON CONFLICT(user_id) DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.choose_account_role(public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.choose_account_role(public.app_role) TO authenticated;
CREATE TABLE public.workers (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, user_id uuid UNIQUE REFERENCES public.profiles(id) ON DELETE CASCADE, is_sample boolean NOT NULL DEFAULT false, name text NOT NULL, category_id text NOT NULL, city text NOT NULL, area text NOT NULL DEFAULT '', rate numeric NOT NULL CHECK(rate>=0), unit text NOT NULL DEFAULT 'per visit', years integer NOT NULL DEFAULT 0 CHECK(years>=0), bio text NOT NULL DEFAULT '' CHECK(char_length(bio)<=300), languages text[] NOT NULL DEFAULT '{}', skills text[] NOT NULL DEFAULT '{}', available text[] NOT NULL DEFAULT '{}', time_slots text[] NOT NULL DEFAULT ARRAY['9:00 AM','11:00 AM','2:00 PM','5:00 PM'], radius numeric NOT NULL DEFAULT 10 CHECK(radius>=0), worker_type text NOT NULL DEFAULT 'Skilled worker', portfolio text[] NOT NULL DEFAULT '{}', rating numeric NOT NULL DEFAULT 0, reviews integer NOT NULL DEFAULT 0, verified boolean NOT NULL DEFAULT false, verification_status text NOT NULL DEFAULT 'Unverified', created_at timestamptz NOT NULL DEFAULT now(), CHECK(cardinality(portfolio)<=6));
GRANT SELECT ON public.workers TO anon, authenticated; GRANT INSERT, UPDATE ON public.workers TO authenticated; GRANT ALL ON public.workers TO service_role;
ALTER TABLE public.workers ENABLE ROW LEVEL SECURITY;
CREATE POLICY workers_public ON public.workers FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY workers_own_insert ON public.workers FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'worker') AND NOT is_sample AND NOT verified AND rating=0 AND reviews=0 AND verification_status='Unverified');
CREATE POLICY workers_own_update ON public.workers FOR UPDATE TO authenticated USING(user_id=auth.uid() AND NOT is_sample AND public.has_role(auth.uid(),'worker')) WITH CHECK(user_id=auth.uid() AND NOT is_sample);
CREATE FUNCTION public.protect_worker_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.role()='authenticated' AND (NEW.is_sample IS DISTINCT FROM OLD.is_sample OR NEW.verified IS DISTINCT FROM OLD.verified OR NEW.rating IS DISTINCT FROM OLD.rating OR NEW.reviews IS DISTINCT FROM OLD.reviews OR NEW.verification_status IS DISTINCT FROM OLD.verification_status OR NEW.id IS DISTINCT FROM OLD.id OR NEW.user_id IS DISTINCT FROM OLD.user_id) THEN RAISE EXCEPTION 'Protected worker fields cannot be changed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_worker_fields BEFORE UPDATE ON public.workers FOR EACH ROW EXECUTE FUNCTION public.protect_worker_fields();
CREATE TABLE public.worker_documents(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, path text NOT NULL, created_at timestamptz DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.worker_documents TO authenticated; GRANT ALL ON public.worker_documents TO service_role;
ALTER TABLE public.worker_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_own ON public.worker_documents FOR ALL TO authenticated USING(user_id=auth.uid() AND public.has_role(auth.uid(),'worker')) WITH CHECK(user_id=auth.uid() AND public.has_role(auth.uid(),'worker'));
CREATE FUNCTION public.pending_document() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.workers SET verification_status='Pending verification' WHERE user_id=NEW.user_id AND NOT is_sample AND NOT verified; RETURN NEW; END $$;
CREATE TRIGGER pending_document AFTER INSERT OR UPDATE ON public.worker_documents FOR EACH ROW EXECUTE FUNCTION public.pending_document();
CREATE TABLE public.bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.profiles(id), worker_id text NOT NULL REFERENCES public.workers(id), day text NOT NULL, time text NOT NULL, note text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Requested' CHECK(status IN ('Requested','Confirmed','Declined','Cancelled')), approved boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.bookings TO authenticated; GRANT ALL ON public.bookings TO service_role;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY bookings_customer_read ON public.bookings FOR SELECT TO authenticated USING(customer_id=auth.uid() AND public.has_role(auth.uid(),'customer'));
CREATE POLICY bookings_worker_read ON public.bookings FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'worker') AND EXISTS(SELECT 1 FROM public.workers w WHERE w.id=worker_id AND w.user_id=auth.uid()));
CREATE POLICY bookings_customer_create ON public.bookings FOR INSERT TO authenticated WITH CHECK(customer_id=auth.uid() AND public.has_role(auth.uid(),'customer') AND status='Requested' AND approved);
CREATE POLICY bookings_customer_cancel ON public.bookings FOR UPDATE TO authenticated USING(customer_id=auth.uid() AND public.has_role(auth.uid(),'customer')) WITH CHECK(customer_id=auth.uid() AND status='Cancelled');
CREATE POLICY bookings_worker_status ON public.bookings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'worker') AND EXISTS(SELECT 1 FROM public.workers w WHERE w.id=worker_id AND w.user_id=auth.uid())) WITH CHECK(status IN ('Confirmed','Declined') AND EXISTS(SELECT 1 FROM public.workers w WHERE w.id=worker_id AND w.user_id=auth.uid()));
CREATE FUNCTION public.validate_booking() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE w public.workers; BEGIN IF TG_OP='UPDATE' THEN IF NEW.customer_id IS DISTINCT FROM OLD.customer_id OR NEW.worker_id IS DISTINCT FROM OLD.worker_id OR NEW.day IS DISTINCT FROM OLD.day OR NEW.time IS DISTINCT FROM OLD.time OR NEW.note IS DISTINCT FROM OLD.note OR NEW.approved IS DISTINCT FROM OLD.approved OR NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'Only booking status may change'; END IF; IF OLD.status NOT IN ('Requested','Confirmed') OR (OLD.status='Confirmed' AND NEW.status<>'Cancelled') THEN RAISE EXCEPTION 'This booking cannot change status'; END IF; ELSE SELECT * INTO w FROM public.workers WHERE id=NEW.worker_id; IF NOT (NEW.day=ANY(w.available)) OR NOT(NEW.time=ANY(w.time_slots)) THEN RAISE EXCEPTION 'That slot is not available'; END IF; IF NOT NEW.approved THEN RAISE EXCEPTION 'Approve this worker, day and time first'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_booking BEFORE INSERT OR UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.validate_booking();
CREATE UNIQUE INDEX one_active_worker_slot ON public.bookings(worker_id,day,time) WHERE status IN ('Requested','Confirmed');
CREATE FUNCTION public.free_worker_slots(worker text, chosen_day text) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(array_agg(t),'{}') FROM public.workers w CROSS JOIN unnest(w.time_slots) t WHERE w.id=worker AND chosen_day=ANY(w.available) AND NOT EXISTS(SELECT 1 FROM public.bookings b WHERE b.worker_id=w.id AND b.day=chosen_day AND b.time=t AND b.status IN ('Requested','Confirmed')) $$;
GRANT EXECUTE ON FUNCTION public.free_worker_slots(text,text) TO anon,authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.bookings;
CREATE TABLE public.threads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL DEFAULT 'New conversation', created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.threads TO authenticated; GRANT ALL ON public.threads TO service_role;
ALTER TABLE public.threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY threads_own ON public.threads FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.chat_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.threads(id) ON DELETE CASCADE, sdk_id text NOT NULL, message jsonb NOT NULL, created_at timestamptz DEFAULT now(), UNIQUE(thread_id,sdk_id));
GRANT SELECT,INSERT,UPDATE ON public.chat_messages TO authenticated; GRANT ALL ON public.chat_messages TO service_role;
ALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY messages_own ON public.chat_messages FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.threads t WHERE t.id=thread_id AND t.user_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.threads t WHERE t.id=thread_id AND t.user_id=auth.uid()));
CREATE TABLE public.agent_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id text NOT NULL, user_id uuid, user_message text NOT NULL, tool_name text NOT NULL, arguments jsonb NOT NULL, result jsonb NOT NULL, created_at timestamptz DEFAULT now());
GRANT SELECT ON public.agent_logs TO authenticated; GRANT ALL ON public.agent_logs TO service_role;
ALTER TABLE public.agent_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY agent_logs_own ON public.agent_logs FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.agent_usage(subject text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), count integer NOT NULL DEFAULT 0);
GRANT ALL ON public.agent_usage TO service_role; ALTER TABLE public.agent_usage ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.consume_agent_message(subject_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE used integer; BEGIN INSERT INTO public.agent_usage(subject,count) VALUES(subject_key,1) ON CONFLICT(subject) DO UPDATE SET count=CASE WHEN public.agent_usage.window_start<now()-interval '1 hour' THEN 1 ELSE public.agent_usage.count+1 END, window_start=CASE WHEN public.agent_usage.window_start<now()-interval '1 hour' THEN now() ELSE public.agent_usage.window_start END RETURNING count INTO used; RETURN used<=20; END $$;
REVOKE ALL ON FUNCTION public.consume_agent_message(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.consume_agent_message(text) TO service_role;
CREATE TABLE public.ai_service_state(id text PRIMARY KEY, paused boolean NOT NULL DEFAULT false, reason text NOT NULL DEFAULT '', status integer NOT NULL DEFAULT 200);
GRANT ALL ON public.ai_service_state TO service_role; ALTER TABLE public.ai_service_state ENABLE ROW LEVEL SECURITY;